        ('onboarding', '/ˈɒnˌbɔːrdɪŋ/', 'n', 'quy trình hội nhập nhân viên mới', 'the action or process of integrating a new employee into an organization', 'A well-structured onboarding process dramatically accelerates new hire productivity.', 'Quy trình hội nhập nhân viên mới có cơ cấu bài bản sẽ giúp đẩy nhanh đáng kể năng suất của tân binh.', ['orientation', 'induction'], ['employee onboarding', 'onboarding workflow'], 'Bring on board the company ship'),
        ('headhunt', '/ˈhɛdˌhʌnt/', 'v', 'săn nhân tài, tuyển mộ lãnh đạo cấp cao', 'to approach and recruit someone who is already working elsewhere for a senior position', 'Executive search firms were retained to headhunt a seasoned Chief Technology Officer.', 'Các công ty tìm kiếm nhân sự cấp cao đã được thuê để săn đón một Giám đốc Công nghệ dày dạn kinh nghiệm.', ['recruit', 'poach'], ['headhunt executives', 'headhunted by rivals'], 'Hunt for top heads/brains'),
        ('benchmarking', '/ˈbɛntʃˌmɑːrkɪŋ/', 'n', 'đối chuẩn đánh giá hiệu suất năng lực', 'evaluating something by comparison with a standard or the best in industry', 'Annual performance reviews include 360-degree talent benchmarking across regional peers.', 'Các đợt đánh giá hiệu suất hàng năm bao gồm việc đối chuẩn nhân tài 360 độ so với các đồng nghiệp khu vực.', ['comparative evaluation'], ['salary benchmarking', 'industry benchmarking'], 'Benchmark against gold standard'),
        ('attrition', '/əˈtrɪʃən/', 'n', 'tỷ lệ hao hụt nhân sự tự nhiên', 'the reduction in workforce size as a result of resignations and retirements', 'The technology consultancy maintained low employee attrition by offering flexible remote options.', 'Công ty tư vấn công nghệ đã duy trì tỷ lệ hao hụt nhân sự thấp bằng việc cung cấp các lựa chọn làm việc từ xa linh hoạt.', ['turnover', 'staff reduction'], ['attrition rate', 'high attrition'], 'Attritio = wearing away naturally'),
        ('deliverables', '/dɪˈlɪvərəblz/', 'n', 'các kết quả bàn giao công việc theo hợp đồng', 'tangible products or results that must be completed and provided under a project contract', 'Candidates must demonstrate a proven track record of meeting strict quarterly deliverables.', 'Các ứng viên phải chứng minh được thành tích ấn tượng trong việc hoàn thành các kết quả bàn giao nghiêm ngặt hàng quý.', ['outputs', 'milestone achievements'], ['key deliverables', 'project deliverables'], 'Things ready to be delivered'),
        ('lateral', '/ˈlætərəl/', 'adj', 'ngang cấp, chuyển vị trí tương đương', 'moving to a role on the same level of hierarchy rather than a promotion', 'She accepted a lateral career move into product marketing to broaden her skill repertoire.', 'Cô đã chấp nhận một bước chuyển ngang cấp sang mảng tiếp thị sản phẩm để mở rộng tập kỹ năng của mình.', ['horizontal', 'cross-functional'], ['lateral move', 'lateral transfer'], 'Latus = side; sideways step'),
        ('exit-interview', '/ˈɛɡzɪt ˌɪntərvjuː/', 'n', 'phỏng vấn thôi việc', 'an interview held with an employee about to leave an organization to gain feedback', 'The HR manager conducted a confidential exit-interview to identify workplace improvement areas.', 'Trưởng phòng nhân sự đã tiến hành một buổi phỏng vấn thôi việc bảo mật nhằm xác định các điểm cần cải tiến nơi công sở.', ['departure debrief'], ['conduct an exit-interview', 'exit-interview feedback'], 'Interview at company exit door'),
