        ('tare-weight', '/ˈtɛər weɪt/', 'n', 'trọng lượng vỏ rỗng của phương tiện / bao bì', 'the weight of an empty vehicle or container, deducted from gross weight to obtain net weight of cargo', 'Weigh stations subtract the tare-weight of the trailer to calculate the exact grain payload.', 'Các trạm cân xe trừ trọng lượng vỏ rỗng của rơ-moóc để tính toán chính xác trọng lượng tịnh của hàng ngũ cốc.', ['empty container weight'], ['tare-weight certification', 'calculate tare-weight'], 'Tare empty shell deduction'),
        ('dunnage', '/ˈdʌnɪdʒ/', 'n', 'vật liệu chèn lót bảo vệ hàng trong khoang tàu', 'loose wood, matting, or inflatable airbags used to protect cargo during an ocean voyage', 'Inflatable dunnage air bags prevent pallets from shifting inside shipping containers at sea.', 'Túi khí chèn lót hàng bằng vật liệu dunnage ngăn các pallet xô lệch bên trong container trên biển.', ['cargo cushioning', 'padding'], ['dunnage bags', 'protective dunnage'], 'Dunnage scrap wood and air cushions'),
        ('demurrage-fee', '/dɪˈmɜːrɪdʒ fiː/', 'n', 'phí phạt lưu bãi container quá hạn quy định', 'a specific financial penalty charged for exceeding the permitted free time at a container terminal', 'Importers scrambled to clear customs to avoid racking up exorbitant daily demurrage-fees.', 'Các nhà nhập khẩu hối hả hoàn tất thủ tục hải quan để tránh phải chịu các khoản phí phạt lưu bãi đắt đỏ.', ['detention fee'], ['pay demurrage-fee', 'daily demurrage-fee'], 'Demur penalty fees'),
        ('bill-of-entry', '/ˌbɪl əv ˈɛntri/', 'n', 'tờ khai hải quan nhập khẩu chính thức', 'a formal legal declaration made by an importer describing goods entering national borders', 'The clearing agent submitted the validated bill-of-entry to the customs boundary official.', 'Đại lý thông quan đã đệ trình tờ khai hải quan nhập khẩu đã được phê duyệt cho cơ quan kiểm soát biên giới.', ['customs declaration'], ['file a bill-of-entry', 'stamped bill-of-entry'], 'Bill documenting entry of cargo'),
