        ('subduction', '/səbˈdʌkʃən/', 'n', 'hiện tượng hút chìm mảng kiến tạo', "the sideways and downward movement of the edge of a plate of the earth's crust into the mantle beneath another plate", 'Oceanic plate subduction under continental plates forms volcanic mountain arcs.', 'Sự hút chìm của mảng kiến tạo đại dương xuống dưới mảng lục địa tạo nên các vòng cung núi lửa.', ['plate collision'], ['subduction zone', 'tectonic subduction'], 'Sub (under) + ducere (lead)'),
        ('flash-flood', '/ˌflæʃ ˈflʌd/', 'n', 'trận lũ quét cục bộ ập đến bất ngờ', 'a sudden local flood of great volume and short duration following torrential rainfall', 'Park rangers warned canyon hikers about deadly flash-floods after afternoon rainstorms.', 'Các kiểm lâm viên đã cảnh báo những người đi bộ trong hẻm núi về những trận lũ quét chết người sau cơn mưa rào buổi chiều.', ['sudden inundation', 'torrential surge'], ['dangerous flash-flood', 'flash-flood warning'], 'Flooding in a flash'),
        ('storm-surge', '/ˈstɔːrm sɜːrdʒ/', 'n', 'nước dâng do bão đánh sập đê biển', 'a rising of the sea as a result of atmospheric pressure changes and wind associated with a storm', 'The category five hurricane drove a twelve-foot storm-surge across coastal barrier islands.', 'Cơn bão cấp 5 đã đẩy mực nước biển dâng do bão cao tới 3,6 mét quét qua các đảo chắn ven bờ.', ['tidal surge', 'sea inundation'], ['deadly storm-surge', 'massive storm-surge'], 'Storm surging the ocean onshore'),
